"""Record the actual built-in imagegen input roles and locks before requesting images."""
from pathlib import Path
import json
ROOT=Path(__file__).resolve().parents[1]
photo=ROOT/'07_renders/v18-entry';tour=ROOT/'07_renders/vr-tour-v04';tour.mkdir(parents=True,exist_ok=True)
style=[str(ROOT/'00_sources/photographic-style-reference-v16.png'),str(ROOT/'07_renders/v12-reference/living-day-realistic-v01.png')]
common='''Use case: style-transfer. Asset: photorealistic residential interior concept.
Image 1 is the EDIT TARGET and ONLY geometry/camera anchor, rendered from the current v18 home model. Image 2 is the homeowner-selected photographic style screenshot, image 3 its clean companion. Transfer only their realistic materials and photographic light; never copy their room layout, crop, UI, furniture or props.
Create convincing modern Japanese architectural photography: clean softly warm matte white, pale low-yellow oak, greige fine linen, muted sage and navy accents. Retain milk-yellow lower corridor cabinets, cream upper cabinets, walnut shallow niches. Real-scale wood grain, subtle woven upholstery, rounded sewn cushion tension, restrained flat-glass reflections, natural foliage, grounded contact shadows, soft indirect bounce. Follow the source oblique daylight with gently edged window shadows and gradual falloff into the room, detailed bright windows and quiet shadow areas. No orange wash, plastic/toy appearance or uniformly lit CGI. Outside is illustrative softly distant trees/sky, not actual site photography.
LOCK all source walls, doors, openings, window divisions, ceiling curves/fixtures, narrow trim, flooring direction, all furniture footprints and orientations. Preserve the 85-inch TV, chaise at the balcony end, coffee table, separate ottoman, double desk behind sofa facing TV, exactly one 34-inch monitor and one office chair, exactly four dining chairs, low round tea table with exactly two low tea chairs, three established floor plants and stacked laundry. Do not invent additional objects, art, rugs, pendants, handles, windows, sofas or decorative collections.
ENTRY CHANGE is already modeled in image 1: on entering through the left-of-plan opening and heading right on plan, RIGHT hand (plan bottom) is a complete 1271W x350D x2750H white shoe cabinet, two door columns, bottom gap160, shallow full-width niche at1200-1400. LEFT hand (toward dining) is the last1000mm of the existing400-deep long cabinet, now a padded shoe bench at450 high, pale oak piano-key hook wall and white upper cabinet starting1800 up to ceiling2750. Preserve 20 narrow timber-key columns in three bands, four keys shown folded out at ends, all other keys flush; not a musical keyboard or ordinary fixed pegs. Warm strip is tucked UNDER UPPER CABINET, never across middle of keys. No bench or hooks in the right shoe cabinet. No new furniture footprint at doorway. Preserve the full-height mirror, glass opening and circulation exactly. Detailed appearance is conceptual; preserve native geometry relationships.
No text, labels, watermark, people or screenshot controls.'''
specs=[]
for ident in ['entry-left','entry-right','living','dining','balcony']:
    note={'entry-left':'Portrait detail of left piano-key bench. Preserve all four projecting angled keys and visible soft bench; retain adjacent cream/milk-yellow closed long cabinet.', 'entry-right':'Portrait overall of right shoe cabinet. Keep the two narrow vertical door columns, full-width200-high wood niche,160 bottom gap and cabinet flush to ceiling. Keep adjacent mirror at image left and glass opening at image right; DO NOT add a bench here.', 'living':'Landscape overall living room. Preserve source framing and all furniture positions.', 'dining':'Landscape dining room. Exactly four chairs with long table edge at existing wall. Entry area beyond must show updated right shoe storage and left piano bench only where actually visible.', 'balcony':'Landscape balcony tea seating. Retain low table and two low chairs, plants, glazing and current sofa position.'}[ident]
    specs.append(dict(id=ident,references=[str(photo/(ident+'-native.png'))]+style,prompt=common+'\nPERSPECTIVE LOCK: Preserve image1 aspect ratio, lens, framing and camera position. Straight architectural edges where source straight, not fisheye. '+note))
(photo/'imagegen-prompts.json').write_text(json.dumps(dict(mode='built-in image_gen',specs=specs),ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
specs=[]
for ident in ['living','dining','balcony','entry']:
    projection='''PROJECTION LOCK: Image1 is a true full360x180 EQUIRECTANGULAR SPHERE, NOT a normal photograph. Output ONE2:1 equirectangular panorama. Preserve every object at the same longitude/latitude, spherical distortions, horizon exactly at mid-height and complete ceiling/floor poles. Keep left and right edges the same meridian with matching material/light for seamless wrap. Do not crop, zoom, flatten into a perspective, mirror or assemble panels. The exact full source sphere must remain visible. Keep source ceiling lights, no repeated ceiling strips or extra furnishings at seam. This is destined for a spherical viewer; top/bottom curvature is essential.'''
    specs.append(dict(id=ident,references=[str(photo/(ident+'-anchor.png'))]+style,prompt=common+'\n'+projection+'\nCurrent observation node: '+ident+'. All architecture and positions must match image1, including updated entry furniture.'))
(tour/'imagegen-prompts.json').write_text(json.dumps(dict(mode='built-in image_gen',specs=specs),ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
print('V18_IMAGEGEN_SPECS_READY',5,4)
